const freeLeadEvents = `-- name: FreeLeadEvents :many
UPDATE lead_events SET held = 0, held_at = NULL WHERE repository = ? AND workstream = ? AND held = 1
RETURNING id, repository, workstream, kind, payload, time, delivered_at, chat_message, issue, held, comment, review, held_at, issue_repository
`

type FreeLeadEventsParams struct {
	Repository string
	Workstream int64
}

func (q *Queries) FreeLeadEvents(ctx context.Context, arg FreeLeadEventsParams) ([]LeadEvent, error) {
	rows, err := q.db.QueryContext(ctx, freeLeadEvents, arg.Repository, arg.Workstream)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []LeadEvent
	for rows.Next() {
		var i LeadEvent
		if err := rows.Scan(
			&i.ID,
			&i.Repository,
			&i.Workstream,
			&i.Kind,
			&i.Payload,
			&i.Time,
			&i.DeliveredAt,
			&i.ChatMessage,
			&i.Issue,
			&i.Held,
			&i.Comment,
			&i.Review,
			&i.HeldAt,
			&i.IssueRepository,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

